```sql
SELECT m.match_date, m.season, p.player_name, SUM(d.runs_scored) AS individual_score FROM Deliveries d JOIN Matches m ON d.match_id = m.match_id JOIN Players p ON d.striker_id = p.player_id WHERE d.batting_team = 'Pakistan' AND m.season LIKE '%World Cup%' GROUP BY d.match_id, d.inning, d.striker_id, p.player_name, m.match_date, m.season ORDER BY individual_score DESC;
```

